DROP TABLE collections;
CREATE TABLE collections ( id int NOT NULL AUTO_INCREMENT, name varchar(256), description varchar(512), date date, yr year, PRIMARY KEY (id) ) ENGINE=InnoDB DEFAULT CHARSET=latin1;
DROP TABLE collections_projects;
CREATE TABLE collections_projects ( collection_id int NOT NULL, project_id int NOT NULL, PRIMARY KEY (collection_id, project_id), CONSTRAINT fk_coll_prog_coll FOREIGN KEY (collection_id) REFERENCES collections (id) , CONSTRAINT fk_coll_prog_prog FOREIGN KEY (project_id) REFERENCES projects (id), INDEX fk_coll_prog_prog (project_id) ) ENGINE=InnoDB DEFAULT CHARSET=latin1;
DROP TABLE customers;
CREATE TABLE customers ( id int NOT NULL AUTO_INCREMENT, name varchar(128), surname varchar(128), company varchar(256), vat varchar(128), fiscal_code varchar(128), email varchar(128), phone1 varchar(128), phone2 varchar(128), fax varchar(128), mobile varchar(128), address varchar(512), zip_code varchar(12), city varchar(128), district varchar(128), country varchar(128), vat_applied double(10,3), PRIMARY KEY (id) ) ENGINE=InnoDB DEFAULT CHARSET=latin1;
