DROP TABLE model_types;
CREATE TABLE model_types ( id int NOT NULL AUTO_INCREMENT, code varchar(25), description varchar(512), PRIMARY KEY (id) ) ENGINE=InnoDB DEFAULT CHARSET=latin1;
insert into model_types (id, code, description) values (1, 'pants', 'pantaloni uomo');
DROP TABLE model_types_sexes;
CREATE TABLE model_types_sexes ( model_type_id int NOT NULL, sex_id int NOT NULL, PRIMARY KEY (model_type_id, sex_id), CONSTRAINT fk_mod_tip_sess_mod_tipo FOREIGN KEY (model_type_id) REFERENCES model_types (id) , CONSTRAINT fk_mod_tip_sess_sess FOREIGN KEY (sex_id) REFERENCES sexes (id), INDEX fk_mod_tip_sess_sess (sex_id) ) ENGINE=InnoDB DEFAULT CHARSET=latin1;
insert into model_types_sexes (model_type_id, sex_id) values (1, 1);
DROP TABLE models;
CREATE TABLE models ( id int NOT NULL AUTO_INCREMENT, name varchar(50), description varchar(512), model_type_id int NOT NULL, sex_id int NOT NULL, image tinyblob, PRIMARY KEY (id), CONSTRAINT fk_mod_mod_tipo FOREIGN KEY (model_type_id, sex_id) REFERENCES model_types_sexes (model_type_id, sex_id), INDEX fk_mod_mod_tipo (model_type_id, sex_id) ) ENGINE=InnoDB DEFAULT CHARSET=latin1;
DROP TABLE models_projects;
CREATE TABLE models_projects ( model_id int NOT NULL, project_id int NOT NULL, PRIMARY KEY (model_id, project_id), CONSTRAINT fk_prog_mod_prog FOREIGN KEY (model_id) REFERENCES models (id) , CONSTRAINT fk_prog_mod_mod FOREIGN KEY (project_id) REFERENCES projects (id), INDEX fk_prog_mod_mod (project_id) ) ENGINE=InnoDB DEFAULT CHARSET=latin1;
DROP TABLE projects;
CREATE TABLE projects ( id int NOT NULL AUTO_INCREMENT, name varchar(256), description varchar(512), PRIMARY KEY (id) ) ENGINE=InnoDB DEFAULT CHARSET=latin1;
DROP TABLE sexes;
CREATE TABLE sexes ( id int NOT NULL AUTO_INCREMENT, code varchar(5), description varchar(512), PRIMARY KEY (id) ) ENGINE=InnoDB DEFAULT CHARSET=latin1;
