DROP TABLE suppliers;
CREATE TABLE suppliers ( id int NOT NULL AUTO_INCREMENT, name varchar(128), surname varchar(128), company varchar(256), vat varchar(128), fiscal_code varchar(128), email varchar(128), phone1 varchar(128), phone2 varchar(128), fax varchar(128), mobile varchar(128), address varchar(512), zip_code varchar(12), city varchar(128), district varchar(128), country varchar(128), PRIMARY KEY (id) ) ENGINE=InnoDB DEFAULT CHARSET=latin1;
